// ---------------------------------------------------------------------------
// Editing one slide of a deck.
//
// A generated deck is almost never finished: a title reads wrong, a bullet is
// two clauses, the note says "point at the chart" when there is no chart. This
// is the smallest edit that fixes those — the four fields a presenter actually
// touches — applied to the stored spec, so the .pptx is rebuilt from the edit
// rather than regenerated by a model.
//
// It runs through the same normaliser the AI output does. That matters: an edit
// is untrusted input too, and `applySlideEdit` must not be a second path that
// can put a 900-character title on a slide the writer would have trimmed.
// ---------------------------------------------------------------------------

import { normalizeSlide, type SlideSpec } from "./spec";

export interface SlideEdit {
  title?: string;
  kicker?: string;
  subtitle?: string;
  /** Bullet points, already split into lines by the caller. */
  body?: string[];
  notes?: string;
}

/** Kinds whose layout actually draws `body`. */
export const BODY_KINDS: SlideSpec["kind"][] = ["bullets", "agenda", "section"];

export function applySlideEdit(slide: SlideSpec, edit: SlideEdit): SlideSpec {
  const merged: Record<string, unknown> = { ...slide };

  // A cleared title is refused rather than accepted: every layout needs one,
  // and the alternative is a slide that renders as its previous title anyway.
  if (edit.title !== undefined && edit.title.trim()) merged.title = edit.title.slice(0, 140);
  if (edit.kicker !== undefined) merged.kicker = edit.kicker.slice(0, 40);
  if (edit.subtitle !== undefined) merged.subtitle = edit.subtitle.slice(0, 220);
  if (edit.body !== undefined) {
    merged.body = edit.body
      .map((line) => line.slice(0, 260))
      .filter((line) => line.trim().length > 0)
      .slice(0, 7);
  }
  if (edit.notes !== undefined) merged.notes = edit.notes.slice(0, 1200);

  // Emptying a field has to remove it: `""` would render an empty eyebrow and
  // an empty subtitle box instead of the layout the slide had before.
  for (const key of ["kicker", "subtitle", "notes"] as const) {
    const value = merged[key];
    if (typeof value === "string" && value.trim() === "") delete merged[key];
  }

  return normalizeSlide(merged) ?? slide;
}
